def place(api, customer_id, sku, quantity):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": sku, "quantity": quantity}]}).body["order_id"]


def test_order_history_for_unknown_customer_is_not_found(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_for_customer_without_orders_is_empty(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_lists_newest_order_first(shop):
    first = place(shop, "c1", "BOOK", 1)
    second = place(shop, "c1", "PEN", 2)
    place(shop, "c2", "PEN", 1)
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert [o["order_id"] for o in orders] == [second, first]


def test_order_history_totals_include_discount(shop):
    oid = place(shop, "c2", "LAMP", 2)
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": oid, "status": "placed",
                     "total_cents": shop.orders.handle_get(oid).body["total_cents"]}
    assert entry["total_cents"] == 10200


def test_order_history_includes_cancelled_orders(shop):
    oid = place(shop, "c1", "BOOK", 1)
    shop.orders.handle_cancel(oid)
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert orders == [{"order_id": oid, "status": "cancelled", "total_cents": 2500}]

